import{_ as t,o as a,c as o,a5 as d}from"./chunks/framework.BfQ7H7Qx.js";const m=JSON.parse('{"title":"3.5 Media Package & Media Campaign (13 FRs)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/04-media-package-campaign/README.md","filePath":"feature/srs/04-media-package-campaign/README.md"}'),c={name:"feature/srs/04-media-package-campaign/README.md"};function n(l,e,i,r,s,g){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="_3-5-media-package-media-campaign-13-frs" tabindex="-1">3.5 Media Package &amp; Media Campaign (13 FRs) <a class="header-anchor" href="#_3-5-media-package-media-campaign-13-frs" aria-label="Permalink to &quot;3.5 Media Package &amp; Media Campaign (13 FRs)&quot;">​</a></h1><p>&gt; <strong>Navigation:</strong> <a href="./../../README.html">← Feature Master Index</a> · <a href="./../README.html">← SRS 141 FRs Index</a> · <a href="./../../../ba/04-media-package-campaign.html">BA Domain Spec</a> · <a href="./../../../ba/12-state-machines.html">State Machines</a> · <a href="./../../../ba/use-cases/03-media-package-campaign.html">Use Cases</a> · <a href="./../../modules/README.html">Module Specs Index</a> · <a href="./../../../rule/feature-workflow.html">Workflow Rule</a></p><p>Canonical specification, technical implementation plan, task breakdown, and unit/acceptance test verification suite for <strong>3.5 Media Package &amp; Media Campaign</strong> (<code>3.5.1 – 3.5.13</code>, <strong>13 Atomic CRUD Functional Requirements</strong>).</p><hr><h2 id="_1-domain-architecture-overview" tabindex="-1">1. Domain Architecture Overview <a class="header-anchor" href="#_1-domain-architecture-overview" aria-label="Permalink to &quot;1. Domain Architecture Overview&quot;">​</a></h2><p>Domain <code>3.5</code> bridges commercial service packaging (<strong>Media Package</strong>), structured campaign execution planning (<strong>Media Campaign</strong>), and supplemental post-deployment client requests (<strong>Content Request</strong>) across a coordinated PostgreSQL + MongoDB persistence boundary:</p><ul><li><strong>Media Package Catalogue, Guest Sharing &amp; Manager-Led Workspace Preparation (<code>3.5.1</code> – <code>3.5.4</code>):</strong><ul><li><strong>Controllers (<code>brandhub-business-service</code>):</strong> <code>MediaPackageController</code>, <code>MediaPackageShareController</code>, <code>WorkspacePackagePlanningController</code>, <code>PackageNegotiationHistoryController</code>, <code>ProfileMatchingController</code> (<code>/media-package-fit</code>).</li><li><strong>Dual Capabilities:</strong><ol><li><strong>Agency Catalogue &amp; Public Guest Sharing:</strong> <code>Owner</code> creates Agency custom packages (<code>POST /api/v1/agencies/{agencyId}/media-package-custom</code> with <code>OfferingModel</code> deliverables, criteria, duration, budget), toggles availability, exports snapshots to PDF/PNG (<code>GET .../export</code>), and issues/revokes public read-only guest share links (<code>GET /api/v1/public/media-packages/{token}</code>).</li><li><strong>Workspace Package Recording, Impact Sync &amp; Negotiation History:</strong> <code>Manager</code> / <code>Owner</code> records or updates the Workspace execution package (<code>PUT /api/v1/workspaces/{workspaceId}/media-package</code> with <code>POST .../impact</code> change-impact preview and <code>POST .../preparation/retry</code>), while retaining legacy/audit negotiation &amp; approval endpoints (<code>selectPackage</code>, <code>negotiateTerms</code>, <code>approvePackage</code>, and immutable <code>package_negotiation_events</code> history).</li></ol></li></ul></li><li><strong>Package-Driven Media Campaign Lifecycle, Timeline, Collaborators &amp; Closure (<code>3.5.5</code> – <code>3.5.9</code>):</strong><ul><li><strong>Controllers:</strong> <code>WorkspaceCampaignController</code> (<code>/api/v1/workspaces/{workspaceId}/campaigns/*</code>), <code>MediaCampaignController</code>, <code>CampaignTimelineController</code>, <code>CampaignCollaboratorController</code>, <code>CampaignClosureController</code>, <code>CampaignSubtaskController</code>.</li><li><strong>Capabilities:</strong> Enforces at most one <code>MediaCampaign</code> per Workspace (<code>DRAFT</code> -&gt; <code>APPROVED</code> -&gt; <code>IN_PROGRESS</code> via <code>CampaignDeploymentService</code> -&gt; <code>COMPLETED</code>), versioned plan/brief updates (<code>campaign_versions</code>), structured Client feedback (<code>campaign_review_events</code>), interactive Gantt/timeline scheduling (<code>CampaignTimelineController</code>), third-party partner tracking (<code>campaign_collaborators</code>: <code>CONTACTED</code>, <code>NEGOTIATING</code>, <code>CONFIRMED</code>, <code>LIVE</code>), pre-closure deliverable verification (<code>/completion-check</code>), and atomic campaign completion (<code>/complete</code>).</li></ul></li><li><strong>Supplemental Client Content Requests (<code>3.5.10</code> – <code>3.5.13</code>):</strong><ul><li><strong>Controllers:</strong> <code>ContentRequestController</code> &amp; <code>ContentRequestReviewController</code> (<code>/api/v1/workspaces/{workspaceId}/content-requests/*</code>) backed by MongoDB <code>content_requests</code> (<code>ContentRequestDocument</code>, <code>ContentRequestStore</code>, <code>ContentRequestReviewStore</code>).</li><li><strong>Lifecycle (<code>PENDING</code> -&gt; <code>IN_PROGRESS</code> -&gt; <code>ACCEPTED</code> | <code>DENIED</code>, or <code>PENDING</code> -&gt; <code>CANCELLED</code>):</strong> Requires an <code>IN_PROGRESS</code> deployed Campaign in the Workspace (<code>BR-31</code>). Explicit <code>Manager</code> receipt (<code>/receive</code>) locks <code>Client</code> edits/cancellations (<code>BR-32</code>), and <code>/accept</code> executes an idempotent MongoDB transaction creating exactly one linked <code>TaskDocument</code> (<code>sourceType = CONTENT_REQUEST</code>, <code>sourceRefId = requestId</code>).</li></ul></li><li><strong>Client Surfaces (<code>brandhub-web</code> &amp; <code>brandhub-mobile-app</code>):</strong><ul><li><strong>Web (<code>brandhub-web</code>):</strong> <code>src/pages/media-package/{index,agency,guest}.tsx</code>, <code>src/pages/campaign/{index,page}.tsx</code>, <code>src/pages/requests/{index,WorkspaceRequestPage}.tsx</code>.</li><li><strong>Mobile (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/more/{MediaPackageScreen,CampaignsScreen,CampaignDetailScreen,ContentRequestsScreen,ContentRequestDetailScreen,ContentRequestFormScreen}.tsx</code>.</li></ul></li></ul><hr><h2 id="_2-functional-requirements-matrix" tabindex="-1">2. Functional Requirements Matrix <a class="header-anchor" href="#_2-functional-requirements-matrix" aria-label="Permalink to &quot;2. Functional Requirements Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">FR ID</th><th style="text-align:left;">UC ID</th><th style="text-align:left;">Function Name</th><th style="text-align:left;">Canonical Roles</th><th style="text-align:left;">Status</th><th style="text-align:left;">Feature Artefacts (<code>spec → plan → task → test</code>)</th></tr></thead><tbody><tr><td style="text-align:left;"><code>3.5.1</code></td><td style="text-align:left;"><code>UC-040</code></td><td style="text-align:left;"><strong>Create Media Package</strong></td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:left;">Implemented</td><td style="text-align:left;"><a href="./3-5-1-create-media-package/spec.html">Spec</a> · <a href="./3-5-1-create-media-package/plan.html">Plan</a> · <a href="./3-5-1-create-media-package/task.html">Task</a> · <a href="./3-5-1-create-media-package/test.html">Test</a></td></tr><tr><td style="text-align:left;"><code>3.5.2</code></td><td style="text-align:left;"><code>UC-041</code></td><td style="text-align:left;"><strong>View Template Media Package</strong></td><td style="text-align:left;"><code>Owner, Manager, Client</code></td><td style="text-align:left;">Implemented</td><td style="text-align:left;"><a href="./3-5-2-view-template-media-package/spec.html">Spec</a> · <a href="./3-5-2-view-template-media-package/plan.html">Plan</a> · <a href="./3-5-2-view-template-media-package/task.html">Task</a> · <a href="./3-5-2-view-template-media-package/test.html">Test</a></td></tr><tr><td style="text-align:left;"><code>3.5.3</code></td><td style="text-align:left;"><code>UC-042</code></td><td style="text-align:left;"><strong>Request Media Package</strong></td><td style="text-align:left;"><code>Owner, Manager, Client</code></td><td style="text-align:left;">Implemented</td><td style="text-align:left;"><a href="./3-5-3-request-media-package/spec.html">Spec</a> · <a href="./3-5-3-request-media-package/plan.html">Plan</a> · <a href="./3-5-3-request-media-package/task.html">Task</a> · <a href="./3-5-3-request-media-package/test.html">Test</a></td></tr><tr><td style="text-align:left;"><code>3.5.4</code></td><td style="text-align:left;"><code>UC-043</code></td><td style="text-align:left;"><strong>Approve Media Package</strong></td><td style="text-align:left;"><code>Owner, Manager, Client</code></td><td style="text-align:left;">Implemented</td><td style="text-align:left;"><a href="./3-5-4-approve-media-package/spec.html">Spec</a> · <a href="./3-5-4-approve-media-package/plan.html">Plan</a> · <a href="./3-5-4-approve-media-package/task.html">Task</a> · <a href="./3-5-4-approve-media-package/test.html">Test</a></td></tr><tr><td style="text-align:left;"><code>3.5.5</code></td><td style="text-align:left;"><code>UC-044</code></td><td style="text-align:left;"><strong>Create Media Campaign</strong></td><td style="text-align:left;"><code>Owner, Manager</code></td><td style="text-align:left;">Implemented</td><td style="text-align:left;"><a href="./3-5-5-create-media-campaign/spec.html">Spec</a> · <a href="./3-5-5-create-media-campaign/plan.html">Plan</a> · <a href="./3-5-5-create-media-campaign/task.html">Task</a> · <a href="./3-5-5-create-media-campaign/test.html">Test</a></td></tr><tr><td style="text-align:left;"><code>3.5.6</code></td><td style="text-align:left;"><code>UC-045</code></td><td style="text-align:left;"><strong>View Media Campaign</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client</code></td><td style="text-align:left;">Implemented</td><td style="text-align:left;"><a href="./3-5-6-view-media-campaign/spec.html">Spec</a> · <a href="./3-5-6-view-media-campaign/plan.html">Plan</a> · <a href="./3-5-6-view-media-campaign/task.html">Task</a> · <a href="./3-5-6-view-media-campaign/test.html">Test</a></td></tr><tr><td style="text-align:left;"><code>3.5.7</code></td><td style="text-align:left;"><code>UC-046</code></td><td style="text-align:left;"><strong>Update Media Campaign</strong></td><td style="text-align:left;"><code>Owner, Manager, Client</code></td><td style="text-align:left;">Implemented</td><td style="text-align:left;"><a href="./3-5-7-update-media-campaign/spec.html">Spec</a> · <a href="./3-5-7-update-media-campaign/plan.html">Plan</a> · <a href="./3-5-7-update-media-campaign/task.html">Task</a> · <a href="./3-5-7-update-media-campaign/test.html">Test</a></td></tr><tr><td style="text-align:left;"><code>3.5.8</code></td><td style="text-align:left;"><code>UC-047</code></td><td style="text-align:left;"><strong>Approve Media Campaign</strong></td><td style="text-align:left;"><code>Owner, Manager, Client</code></td><td style="text-align:left;">Implemented</td><td style="text-align:left;"><a href="./3-5-8-approve-media-campaign/spec.html">Spec</a> · <a href="./3-5-8-approve-media-campaign/plan.html">Plan</a> · <a href="./3-5-8-approve-media-campaign/task.html">Task</a> · <a href="./3-5-8-approve-media-campaign/test.html">Test</a></td></tr><tr><td style="text-align:left;"><code>3.5.9</code></td><td style="text-align:left;"><code>UC-048</code></td><td style="text-align:left;"><strong>Complete Media Campaign</strong></td><td style="text-align:left;"><code>Owner, Manager</code></td><td style="text-align:left;">Implemented</td><td style="text-align:left;"><a href="./3-5-9-complete-media-campaign/spec.html">Spec</a> · <a href="./3-5-9-complete-media-campaign/plan.html">Plan</a> · <a href="./3-5-9-complete-media-campaign/task.html">Task</a> · <a href="./3-5-9-complete-media-campaign/test.html">Test</a></td></tr><tr><td style="text-align:left;"><code>3.5.10</code></td><td style="text-align:left;"><code>UC-049</code></td><td style="text-align:left;"><strong>Create Content Request</strong></td><td style="text-align:left;"><code>Owner, Manager, Client</code></td><td style="text-align:left;">Implemented</td><td style="text-align:left;"><a href="./3-5-10-create-content-request/spec.html">Spec</a> · <a href="./3-5-10-create-content-request/plan.html">Plan</a> · <a href="./3-5-10-create-content-request/task.html">Task</a> · <a href="./3-5-10-create-content-request/test.html">Test</a></td></tr><tr><td style="text-align:left;"><code>3.5.11</code></td><td style="text-align:left;"><code>UC-050</code></td><td style="text-align:left;"><strong>Track Request Status</strong></td><td style="text-align:left;"><code>Owner, Manager, Client</code></td><td style="text-align:left;">Implemented</td><td style="text-align:left;"><a href="./3-5-11-track-request-status/spec.html">Spec</a> · <a href="./3-5-11-track-request-status/plan.html">Plan</a> · <a href="./3-5-11-track-request-status/task.html">Task</a> · <a href="./3-5-11-track-request-status/test.html">Test</a></td></tr><tr><td style="text-align:left;"><code>3.5.12</code></td><td style="text-align:left;"><code>UC-051</code></td><td style="text-align:left;"><strong>Update Request</strong></td><td style="text-align:left;"><code>Owner, Manager, Client</code></td><td style="text-align:left;">Implemented</td><td style="text-align:left;"><a href="./3-5-12-update-request/spec.html">Spec</a> · <a href="./3-5-12-update-request/plan.html">Plan</a> · <a href="./3-5-12-update-request/task.html">Task</a> · <a href="./3-5-12-update-request/test.html">Test</a></td></tr><tr><td style="text-align:left;"><code>3.5.13</code></td><td style="text-align:left;"><code>UC-052</code></td><td style="text-align:left;"><strong>Cancel Request</strong></td><td style="text-align:left;"><code>Owner, Manager, Client</code></td><td style="text-align:left;">Implemented</td><td style="text-align:left;"><a href="./3-5-13-cancel-request/spec.html">Spec</a> · <a href="./3-5-13-cancel-request/plan.html">Plan</a> · <a href="./3-5-13-cancel-request/task.html">Task</a> · <a href="./3-5-13-cancel-request/test.html">Test</a></td></tr></tbody></table><hr><h2 id="_3-core-business-rules-hybrid-persistence-invariants" tabindex="-1">3. Core Business Rules &amp; Hybrid Persistence Invariants <a class="header-anchor" href="#_3-core-business-rules-hybrid-persistence-invariants" aria-label="Permalink to &quot;3. Core Business Rules &amp; Hybrid Persistence Invariants&quot;">​</a></h2><ul><li><strong><code>BR-25</code> &amp; <code>BR-26</code> (Snapshot Isolation &amp; Append-Only Package Terms):</strong> Workspace packages snapshot <code>final_terms</code> independently of Agency catalogue templates so editing an Agency package never mutates existing Workspace agreements or deployed Campaigns. Append-only <code>package_negotiation_events</code> preserve audit history.</li><li><strong><code>BR-27</code>–<code>BR-29</code> (Single Campaign per Workspace &amp; Version-Locked Deployment):</strong> Each Workspace holds at most one <code>MediaCampaign</code> (<code>UNIQUE(workspace_media_package_id)</code>). Deployment (<code>POST .../deploy</code>) locks package deliverables and materializes MongoDB <code>TaskDocument</code> items idempotently (<code>campaign_deployments</code>).</li><li><strong><code>BR-30</code> (Verified Campaign Closure):</strong> Completing a Campaign (<code>/completion-check</code> + <code>/complete</code>) validates open tasks, automatically cancels remaining <code>PENDING</code> Content Requests with audit provenance, and locks post-completion task/request creation.</li><li><strong><code>BR-31</code> &amp; <code>BR-32</code> (Deployed Campaign Gate &amp; Receipt Lock on Content Requests):</strong> Creating a Content Request requires an <code>IN_PROGRESS</code> Campaign with <code>SUCCEEDED</code> deployment and a <code>dueDate</code> within <code>[max(today, startDate), endDate]</code>. Explicit <code>Manager</code> receipt (<code>PENDING -&gt; IN_PROGRESS</code>) atomically locks <code>Client</code> edit and cancel actions.</li></ul><h2 id="_4-cross-references" tabindex="-1">4. Cross-References <a class="header-anchor" href="#_4-cross-references" aria-label="Permalink to &quot;4. Cross-References&quot;">​</a></h2><ul><li><strong>BA Domain Specification:</strong> <a href="./../../../ba/04-media-package-campaign.html">04-media-package-campaign.md</a> · <a href="./../../../ba/12-state-machines.html">12-state-machines.md</a></li><li><strong>BA System Overview:</strong> <a href="./../../../ba/README.html">BA Overview</a></li><li><strong>Consolidated Feature Modules:</strong> <a href="./../../modules/README.html">Module Specs Index</a></li></ul>',15)])])}const h=t(c,[["render",n]]);export{m as __pageData,h as default};
